    # 偶环/树/网格 → 二分；三角环 → 非二分
    assert is_bipartite(4, [(0, 1), (1, 2), (2, 3)])[0] is True       # 链
    assert is_bipartite(4, [(0, 1), (1, 2), (2, 3), (3, 0)])[0] is True  # 偶环
    assert is_bipartite(3, [(0, 1), (1, 2), (2, 0)])[0] is False       # 奇环
